// record-story: AI Studio in-page runner. Generated by plan.mjs; paste the whole file into the
// generate-speech page (The Master Storyteller open, one real click made in the page first).
// It does the AI Studio Voice Runner's "One speech block per run" steps (tools/ai-studio-voice-runner/
// content.js) for every block: one speech block, its voice, its style, its text, Filler words off, Run,
// wait for the full take. Takes are kept in the page until save() downloads them as one bundle.
//
//   __rec.start()            voice every block not yet taken (returns at once; it runs in the page)
//   await __rec.wait(35)     wait up to 35 s (stay under the browser tool's ~45 s limit), then status
//   __rec.status()           { status, current, done, total, problems, log }
//   __rec.retake(["B016"])   drop those takes and voice them again
//   __rec.stop()             stop after the current take
//   await __rec.save()       download every take as <slug>-takes.bin (one file: no multi-download prompt)
window.__recBlocks = __BLOCKS__;
window.__recSlug = __SLUG__;
(() => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const vis = e => !!e && e.getBoundingClientRect().width > 0;
  const $$ = (s, root = document) => [...root.querySelectorAll(s)];
  async function waitFor(fn, ms = 5000) { const t = Date.now(); while (Date.now() - t < ms) { const v = fn(); if (v) return v; await sleep(100); } return null; }
  function setValue(el, v) { const proto = el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype; Object.getOwnPropertyDescriptor(proto, "value").set.call(el, v); el.dispatchEvent(new Event("input", { bubbles: true })); el.dispatchEvent(new Event("change", { bubbles: true })); }
  const blocks = () => $$("ms-speech-block");
  const voiceOf = b => ((b.querySelector(".voice-chip-label")?.innerText || "").trim()).replace(/^Speaker\s*\d+\s*-\s*/i, "").trim();
  async function closePanels() { for (const b of $$('button[aria-label="Close panel"]').filter(vis)) { b.click(); await sleep(400); } }
  async function closeOverlays() { for (let i = 0; i < 3; i++) { const bd = $$(".cdk-overlay-backdrop").find(vis); if (!bd) break; bd.click(); await sleep(250); } }
  function pageError() { return $$("mat-snack-bar-container, .mat-mdc-snack-bar-container, [role=alert], ms-error-message").filter(vis).map(e => e.innerText.replace(/\s+/g, " ").trim()).filter(Boolean).join(" | "); }
  async function fillerOff() { const sw = $$('button[role="switch"][aria-label="Filler words"]').find(vis); if (sw && sw.getAttribute("aria-checked") === "true") { sw.click(); await sleep(500); } }
  const audioSrc = () => { const a = document.querySelector("ms-audio-footer audio"); return a ? (a.currentSrc || a.src || "") : ""; };
  const runBtn = () => $$("ms-run-button button").find(vis);
  const running = () => /\bstop\b/i.test(runBtn()?.innerText || "");
  const words = t => t.split(/\s+/).filter(w => /\w/.test(w)).length;

  async function setBlock(b) {
    if (!blocks().length) throw new Error("No speech block on the page: open The Master Storyteller first.");
    await closeOverlays(); await closePanels();
    while (blocks().length > 1) { const n = blocks().length; blocks()[n - 1].querySelector('button[aria-label="Delete speech block"]').click(); await waitFor(() => blocks().length < n, 3000); }
    const block = blocks()[0];
    if (voiceOf(block).toLowerCase() !== b.voice.toLowerCase()) {
      block.querySelector(".voice-chip").click();
      const search = await waitFor(() => $$('input[aria-label="Search voices"]').find(vis), 5000);
      if (!search) throw new Error("Voice search not found");
      setValue(search, b.voice);
      const btn = await waitFor(() => $$("ms-voice-library button.voice-card-content").find(x => vis(x) && (x.getAttribute("aria-label") || "").replace(/\s*\(Current\)\s*$/i, "").toLowerCase() === b.voice.toLowerCase()), 8000);
      if (!btn) throw new Error(`Voice ${b.voice} not found`);
      btn.click(); await sleep(700); await closePanels();
      if (voiceOf(blocks()[0]).toLowerCase() !== b.voice.toLowerCase()) throw new Error(`Voice did not stick (${voiceOf(blocks()[0])})`);
    }
    blocks()[0].querySelector('button[aria-label="Style"]').click();
    const ta = await waitFor(() => $$('textarea[aria-label="Describe the voice style"]').find(vis), 4000);
    if (!ta) throw new Error("Style box not found");
    ta.focus(); setValue(ta, b.style); await sleep(200);
    for (const t of ["keydown", "keypress", "keyup"]) ta.dispatchEvent(new KeyboardEvent(t, { key: "Enter", code: "Enter", keyCode: 13, which: 13, bubbles: true, cancelable: true }));
    await sleep(400); await closeOverlays();
    const tx = blocks()[0].querySelector('textarea[aria-label="Speech block text"]');
    setValue(tx, b.text); await sleep(150);
    if (tx.value !== b.text) throw new Error("The text did not stick");
  }

  // Done = Run idle, a new data: URL past the 0.04 s stub, unchanged for 1.5 s (the take plays through first).
  async function runTake(timeoutMs) {
    await fillerOff();
    const before = audioSrc();
    runBtn().click();
    const t0 = Date.now(); let last = before, same = Date.now();
    while (Date.now() - t0 < timeoutMs) {
      await sleep(500);
      const e = pageError(); if (e && /quota|error|failed|exceeded|limit/i.test(e)) throw new Error("AI Studio: " + e);
      const s = audioSrc(); if (s !== last) { last = s; same = Date.now(); }
      if (!running() && s !== before && s.startsWith("data:audio") && s.length > 20000 && Date.now() - same > 1500)
        return { dataUrl: s, duration: document.querySelector("ms-audio-footer audio")?.duration || 0 };
    }
    throw new Error("Timed out waiting for the take (is the tab's sound on, and was the page clicked once?)");
  }

  const R = window.__rec = window.__rec || { takes: {}, info: {}, log: [], state: "idle" };
  R.status = () => {
    const all = window.__recBlocks;
    return { status: R.state, current: R.current || null, done: all.filter(b => R.takes[b.id]).length, total: all.length,
      problems: Object.entries(R.info).filter(([, v]) => v.flag).map(([id, v]) => `${id}: ${v.flag}`), log: R.log.slice(-6) };
  };
  R.wait = async (s = 35) => { const t = Date.now(); while (R.state === "running" && Date.now() - t < s * 1000) await sleep(500); return R.status(); };
  R.stop = () => { R.halt = true; return "stopping after the current take"; };
  R.retake = ids => { for (const id of ids) { delete R.takes[id]; delete R.info[id]; } return R.start(); };
  R.start = () => {
    if (R.state === "running") return "already running";
    R.state = "running"; R.halt = false;
    (async () => {
      for (const b of window.__recBlocks) {
        if (R.halt) break;
        if (R.takes[b.id]) continue;
        R.current = b.id;
        let ok = false;
        for (let attempt = 1; attempt <= 2 && !ok && !R.halt; attempt++) {
          try {
            await setBlock(b);
            const n = words(b.text);
            const r = await runTake(Math.max(60000, n * 1500 + 40000));
            const wps = r.duration ? n / r.duration : 0;
            // A storyteller reads 1.7 to 2.25 words/s; much faster on a long block means skipped words.
            const flag = n >= 12 && (wps > 2.6 || wps < 1.3) ? `odd pace ${wps.toFixed(2)} words/s: listen, retake if words are missing` : "";
            R.takes[b.id] = r.dataUrl; R.info[b.id] = { seconds: +r.duration.toFixed(2), words: n, wps: +wps.toFixed(2), flag };
            R.log.push(`${b.id} ${b.voice} ${r.duration.toFixed(1)} s, ${n} words, ${wps.toFixed(2)} w/s${flag ? " ⚠" : ""}`);
            ok = true;
          } catch (e) {
            R.log.push(`${b.id} attempt ${attempt} FAILED: ${e.message}`);
            if (/quota|exceeded|limit/i.test(e.message)) { R.halt = true; R.state = "quota"; break; }
            await sleep(3000);
          }
        }
        if (!ok) { if (R.state !== "quota") R.state = `stopped at ${b.id}`; R.current = null; return; }
        await sleep(3000);
      }
      R.state = R.halt ? "stopped" : "done"; R.current = null;
    })();
    return "started";
  };
  R.save = async () => {
    const ids = window.__recBlocks.map(b => b.id).filter(id => R.takes[id]);
    const bufs = [];
    for (const id of ids) bufs.push(new Uint8Array(await (await fetch(R.takes[id])).arrayBuffer()));
    const header = new TextEncoder().encode(JSON.stringify({ slug: window.__recSlug, takes: ids.map((id, i) => ({ id, bytes: bufs[i].length, ...R.info[id] })) }));
    const len = new Uint8Array(4); new DataView(len.buffer).setUint32(0, header.length, true);
    const blob = new Blob([len, header, ...bufs], { type: "application/octet-stream" });
    const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${window.__recSlug}-takes.bin`;
    document.body.appendChild(a); a.click(); a.remove();
    return { file: `${window.__recSlug}-takes.bin`, takes: ids.length, bytes: blob.size };
  };
})();
`record-story runner ready: ${window.__recBlocks.length} blocks for ${window.__recSlug}`;
